class Solution { public:vector<int> topStudents(vector<string>& positiveFeedback,vector<string>& negativeFeedback,vector<string>& report,vector<int>& studentId,int k){unordered_set<string> positive(positiveFeedback.begin(),positiveFeedback.end()),negative(negativeFeedback.begin(),negativeFeedback.end());vector<pair<int,int>> students;for(int i=0;i<(int)report.size();++i){stringstream stream(report[i]);string word;int score=0;while(stream>>word){if(positive.count(word))score+=3;if(negative.count(word))--score;}students.push_back({-score,studentId[i]});}sort(students.begin(),students.end());vector<int> answer;for(int i=0;i<k;++i)answer.push_back(students[i].second);return answer;} };
